# Camera / image token: full wrapped status.
p=Path('lib/delivery-image.js'); s=p.read_text()
if 'function wrapAtlasText(' not in s:
    insert="""function wrapAtlasText(str,face,maxWidth){\n  const words=String(str||'').trim().split(/\\s+/).filter(Boolean); if(!words.length)return []; const lines=[]; let line='';\n  for(const word of words){ const candidate=line?`${line} ${word}`:word; if(!line||textWidth(candidate,face)<=maxWidth){line=candidate;continue;} lines.push(line); line=word; }\n  if(line)lines.push(line); return lines;\n}\nfunction drawAtlasWrappedText(c,x,y,str,face,col,maxWidth,lineHeight=26,align='left'){\n  const lines=wrapAtlasText(str,face,maxWidth); for(let i=0;i<lines.length;i++) drawAtlasText(c,x,y+i*lineHeight,lines[i],face,col,maxWidth,align); return lines.length;\n}\n"""
    s=s.replace('function blitScaled(c,img,dx,dy,dw,dh){',insert+'function blitScaled(c,img,dx,dy,dw,dh){')
s=s.replace("  drawAtlasText(c,102,47,opts.sender||'PostNL','bold30',primary,455); drawAtlasText(c,738,54,opts.status||'','regular22',secondary,150,'right');", "  drawAtlasText(c,102,47,opts.sender||'PostNL','bold30',primary,365); drawAtlasWrappedText(c,738,42,opts.status||'','regular22',secondary,265,25,'right');")
